for r in range(6):
    for c in range(14):
        if (test_in[r][c] == 2 and test_in[r][c+1] == 2 and
            test_in[r+1][c] == 2 and test_in[r+1][c+1] == 2):
                all_blocks.append((r, c))

print(f"All blocks: {all_blocks}")

# For each block, check if any block above it (r < curr_r) shares a column
has_incoming = {}
for r, c in all_blocks:
    has_incoming[(r, c)] = False  # Assume no incoming unless found
    # Check for incoming blocks
    for block_r, block_c in all_blocks:
        if block_r <= r:  # Same row pair or above
            if test_in[block_r][block_c] == 2 and test_in[block_r][block_c+1] == 2:
                # Check if columns overlap
                cols1 = {block_c, block_c + 1}
                cols2 = {c, c + 1}
                if cols1.intersection(cols2):
                    has_incoming[(r, c)] = True
                    break

print("\nHas incoming (from same or upper row pair with shared column):")
for block in all_blocks:
    print(f"  {block}: {has_incoming[block]}")

# Blocks without incoming should stay as 2, blocks with incoming should change to 8
print("\n\nPrediction:")
for block in all_blocks:
    if has_incoming[block]:
        print(f"  {block}: changes to 8")
    else:
        print(f"  {block}: stays as 2")

# Let me construct the expected output grid
height, width = len(test_in), len(test_in[0])
output_grid = [list(row) for row in test_in]

for r, c in all_blocks:
    if has_incoming[(r, c)]:
        for i in range(r, r+2):
            for j in range(c+1):  # cols c and c+1
                if i < height and j < width:
                    output_grid[i][j] = 8
    # Else: no changes

print("\n\nPredicted output grid:")
for row in output_grid:
    print(' '.join(str(x) for x in row))

