demo3_stays = {(0,6), (2,2), (5,11)}
demo3_changes = {(1,13), (3,8), (4,5), (5,0)}

print("Testing (r+c) mod N, checking if sets are different:")
for N in range(3, 10):
    stay_mod = {(b[0]+b[1])%N for b in demo3_stays}
    change_mod = {(b[0]+b[1])%N for b in demo3_changes}
    if stay_mod != change_mod and stay_mod.isdisjoint(change_mod):
        print(f"N={N}: {stay_mod} disjoint from {change_mod}")
    elif stay_mod and change_mod:
        print(f"N={N}: {stay_mod} overlap with {change_mod}")

print("\nCol mod N:")
for N in range(3, 10):
    stay_mod = {b[1]%N for b in demo3_stays}
    change_mod = {b[1]%N for b in demo3_changes}
    if stay_mod.isdisjoint(change_mod):
        print(f"N={N}: {stay_mod} disjoint from {change_mod} ✓")
    else:
        print(f"N={N}: {stay_mod} and {change_mod} overlap")

